arguments.argument:
if obj_draw.click_number>-1
{
add=get_open_filename("PNG파일을 선택해주세요|*.PNG", "")

if add!=""
{
sk_dlrc_load(global.fodre+string(obj_draw.click_number)+".dlrc", "+|+")

file_copy(add, string(dlrc_max_number)+".png")

max_files=0
sk_dlrc_file_list(string(dlrc_max_number)+".png")

for(i=0; i!=max_files; i+=1)
{
sk_dlrc_add(global.fodre+string(obj_draw.click_number)+".dlrc", i, "+|+", 30)
}
//압축하기

for(i=0; i!=max_files; i+=1){sk_dlrc_delete_2("", i)}

sk_res()
//지형불르기
}
}
